                                _total_t = (_tushare_up or 0) + (_tushare_dn or 0)
                                _up_ratio = _tushare_up / _total_t if _total_t > 0 else 0.5
                                if _tushare_zt >= 80 and _up_ratio >= 0.7: emo_stage = "高潮"
