            tk.Label(dlg, text="配置 GitHub Gist 后, 任何电脑保存自动 push, 打开自动 pull+合并",
                     bg="#263238", fg="#90A4AE", font=("", 9), wraplength=440).pack(pady=(0, 8))

            # 步骤说明
            tip_f = tk.Frame(dlg, bg="#37474F"); tip_f.pack(fill=tk.X, padx=16, pady=(0,6))
