    def _canvas_size(self, canvas, w_min=200, h_min=80):

        """从 Canvas 取实际宽高, 未布局完成时用 min 值"""

        try:

            w = max(w_min, canvas.winfo_width())

            h = max(h_min, canvas.winfo_height())

        except Exception:

            w, h = w_min, h_min

        return w, h


