        # 图例
        _leg = [("🧊冰点","#455A64"),("💥退潮","#4CAF50"),("📉震荡","#B0BEC5"),("🚀启动","#2196F3"),("🌱发酵","#FF9800"),("🔥高潮","#EF5350")]
