        tk.Label(top_f, text="| 情绪周期六阶段:", bg="#1E1E2E", fg="#888", font=("Helvetica", _FS["v"])).pack(side=tk.RIGHT, padx=(10,4))

        heatmap_canvas = tk.Canvas(t1, bg="#1E1E2E", height=180, highlightthickness=0)
