            {"key": "daily", "title": "daily(日线K - 股票)", "needs_ts_code": True},
            {"key": "index_daily", "title": "index_daily(日线K - 指数)", "needs_ts_code": True},
            {"key": "moneyflow", "title": "moneyflow(资金流)", "needs_ts_code": True},
