                dapan_data["emo"]["zt"] = zt if 'zt' in dir() else 0
                dapan_data["emo"]["dt"] = dt if 'dt' in dir() else 0

                # --- 热门/冷门板块 (多源 fallback, 热门12+冷门9) ---
