        tag1 = "⚠️ 该回乡下去躲一躲！" if is_bad_stage else "✅ 情绪健康"
        col1 = "#B71C1C" if is_bad_stage else "#1B5E20"
        tk.Label(f1, text=tag1, bg="#263238", fg=col1, font=("", 11, "bold")).pack(anchor="w", pady=(2, 0))

        # ---------- 维度2: 同花顺 (手工) ----------
