                            wall_canvas.configure(yscrollcommand=wall_scrollbar.set)
                            wall_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
                            wall_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
