            news_table_label = ttk.Label(news_left_content, text="资讯数据列表", font=("TkDefaultFont", 12, "bold"))
            news_table_label.pack(anchor=tk.W, pady=(0, 5))
            news_table_frame = ttk.Frame(news_left_content)
