            ttk.Button(lhb_button_frame, text="关闭", command=db_window.destroy).pack(side=tk.RIGHT, padx=5)
            # 初始加载龙虎榜数据
            refresh_lhb_data()
            # ==================== 股票实时数据标签页 ====================
