    def _get_holding_group_data(self, group_index):
        """获取指定持仓组的数据结构
        Args:
            group_index: 持仓组索引(1-5)
        Returns:
            tuple: (holding_stocks, holding_labels, holding_kelly_results, holding_low_diff_results)
        """
        if group_index == 1:
            return self.holding_stocks, self.holding_labels, self.holding_kelly_results, self.holding_low_diff_results
        else:
            holding_stocks = getattr(self, f'holding_stocks_{group_index}')
            holding_labels = getattr(self, f'holding_labels_{group_index}')
            holding_kelly_results = getattr(self, f'holding_kelly_results_{group_index}')
            holding_low_diff_results = getattr(self, f'holding_low_diff_results_{group_index}')
            return holding_stocks, holding_labels, holding_kelly_results, holding_low_diff_results
    def _check_buy_signal(self):
        """检查持仓股是否有买入信号(收盘价上穿主力成本线)"""
        buy_signal_stocks = []
        try:
            for group_index in range(1, 6):
                holding_stocks, _, _, _ = self._get_holding_group_data(group_index)
                for stock in holding_stocks:
                    if not stock or not stock[0] or not stock[1]:
                        continue
                    stock_code = str(stock[1]).strip()
                    stock_name = str(stock[0]).strip()
                    try:
                        kline_data = self._get_daily_kline_data_tushare(stock_code, days=30)
                        if kline_data and 'ma_values' in kline_data and 'vwap' in kline_data['ma_values']:
                            closes = kline_data['data']['收盘'].values
                            vwap_values = kline_data['ma_values']['vwap']
                            if len(closes) >= 2 and len(vwap_values) >= 2:
                                last_close = closes[-1]
                                prev_close = closes[-2]
                                last_vwap = vwap_values[-1]
                                prev_vwap = vwap_values[-2]
                                # 买入信号:收盘价上穿主力成本线(今日收盘 > VWAP,昨日收盘 < VWAP)
                                if last_close > last_vwap and prev_close < prev_vwap:
                                    buy_signal_stocks.append(f"{stock_name}({stock_code})")
                    except Exception as e:
                        print(f"[买入信号检测] 检查股票 {stock_code} 失败: {e}")
        except Exception as e:
            print(f"[买入信号检测] 整体检测失败: {e}")
        try:
            if hasattr(self, 'buy_signal_label'):
                if buy_signal_stocks:
                    self.buy_signal_label.config(text="本买: " + ", ".join(buy_signal_stocks))
                else:
                    self.buy_signal_label.config(text="")
        except Exception as e:
            print(f"[买入信号检测] 更新标签失败: {e}")
        return buy_signal_stocks
    def _export_all_holdings(self):
        """导出所有持仓标签页的股票到TXT文件
        导出规则:
        - 每个持仓标签页导出前20个股票
        - 包含日期时间
        - 保存到 Export 目录
        - 格式:单纯股票名字列表
        """
        try:
            import subprocess
            from tkinter import messagebox
            # 确保导出目录存在
            os.makedirs(D_EXPORT_DIR, exist_ok=True)
            # 生成文件名(包含日期时间)
            current_time = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"持仓导出_{current_time}.txt"
            filepath = os.path.join(D_EXPORT_DIR, filename)
            # 收集所有持仓标签页的股票
            all_stocks = []
            # 遍历所有持仓组(1-14)
            for group_index in range(1, 15):
                holding_stocks, _, _, _ = self._get_holding_group_data(group_index)
                # 只取前20个股票
                for i, stock in enumerate(holding_stocks[:20]):
                    if stock and stock[0]:  # stock 是 (stock_name, stock_code) 元组
                        stock_name = stock[0]
                        stock_code = stock[1] if len(stock) > 1 else ""
                        # 只导出有效的股票代码(6位数字)
                        if stock_code and stock_code.isdigit() and len(stock_code) == 6:
                            all_stocks.append({
                                'code': stock_code,
                                'name': stock_name,
                                'group': group_index
                            })
            # 如果没有股票,提示用户
            if not all_stocks:
                messagebox.showinfo("提示", "当前没有持仓股票可导出")
                return
            # 写入文件(只保存股票名字列表)
            with open(filepath, 'w', encoding='utf-8') as f:
                # 写入股票名称,每行一个
                for stock in all_stocks:
                    f.write(f"{stock['name']}\n")
            # 显示成功消息
            messagebox.showinfo("导出成功",
                           f"已成功导出 {len(all_stocks)} 只股票到:\n{filepath}\n\n"
                           f"文件已自动打开,方便拷贝导入到同花顺自选股")
            # 自动打开文件
            try:
                print(f"尝试打开文件: {filepath}")
                print(f"操作系统类型: {os.name}")
                if os.name == 'darwin':  # macOS
                    print("使用 open 命令")
                    result = subprocess.run(['open', filepath], capture_output=True, text=True)
                    print(f"命令执行结果: {result.returncode}")
                    if result.stderr:
                        print(f"错误信息: {result.stderr}")
                elif os.name == 'nt':  # Windows
                    print("使用 start 命令")
                    result = subprocess.run(['start', filepath], shell=True, capture_output=True, text=True)
                    print(f"命令执行结果: {result.returncode}")
                    if result.stderr:
                        print(f"错误信息: {result.stderr}")
                elif os.name == 'posix':  # Linux
                    print("使用 xdg-open 命令")
                    result = subprocess.run(['xdg-open', filepath], capture_output=True, text=True)
                    print(f"命令执行结果: {result.returncode}")
                    if result.stderr:
                        print(f"错误信息: {result.stderr}")
            except Exception as open_err:
                # 打开文件失败不影响导出结果
                print(f"打开文件失败: {open_err!s}")
        except Exception as e:
            from tkinter import messagebox
            messagebox.showerror("导出失败", f"导出持仓失败:{e!s}")
    def _edit_window_title(self):
        """修改窗口标题"""
        try:
            from tkinter import messagebox, simpledialog
            # 获取当前标题
            current_title = self.root.title()
            # 打开对话框让用户输入新标题
            new_title = simpledialog.askstring(
                "修改窗口标题",
                "请输入新的窗口标题:",
                initialvalue=current_title,
                parent=self.root
            )
            # 如果用户点击了取消或输入为空,不做处理
            if new_title is None:
                return
            new_title = new_title.strip()
            if not new_title:
                messagebox.showinfo("提示", "标题不能为空")
                return
            # 更新窗口标题
            self.root.title(new_title)
            # 更新配置并保存
            global APP_CONFIG
            APP_CONFIG["window_title"] = new_title
            save_app_config(APP_CONFIG)
            # 显示成功消息
            messagebox.showinfo("成功", "窗口标题已修改并保存")
        except Exception as e:
            from tkinter import messagebox
            messagebox.showerror("错误", f"修改标题失败:{e!s}")
    def _open_settings_dialog(self):
        """打开设置对话框"""
        try:
            from tkinter import (
                Button,
                Entry,
                IntVar,
                Label,
                StringVar,
                Toplevel,
                colorchooser,
                messagebox,
            )
            # 创建设置窗口
            settings_window = Toplevel(self.root)
            settings_window.title("设置")
            settings_window.geometry("400x300")
            settings_window.transient(self.root)
            settings_window.grab_set()
            # 获取当前设置
            current_title = self.root.title()
            current_font_size = APP_CONFIG.get("font_size", DEFAULT_APP_CONFIG["font_size"])
            current_color = APP_CONFIG.get("title_color", DEFAULT_APP_CONFIG["title_color"])
            # 标题设置
            Label(settings_window, text="窗口标题:").grid(row=0, column=0, padx=10, pady=10, sticky="w")
            title_var = StringVar(value=current_title)
            Entry(settings_window, textvariable=title_var, width=30).grid(row=0, column=1, padx=10, pady=10)
            # 字体大小设置
            Label(settings_window, text="字体大小:").grid(row=1, column=0, padx=10, pady=10, sticky="w")
            font_size_var = IntVar(value=current_font_size)
            Entry(settings_window, textvariable=font_size_var, width=10).grid(row=1, column=1, padx=10, pady=10, sticky="w")
            # 颜色设置
            Label(settings_window, text="标题颜色:").grid(row=2, column=0, padx=10, pady=10, sticky="w")
            color_var = StringVar(value=current_color)
            def choose_color():
                color = colorchooser.askcolor(title="选择颜色")
                if color[1]:
                    color_var.set(color[1])
                    color_button.config(bg=color[1])
            color_button = Button(settings_window, text="选择颜色", command=choose_color, width=10, bg=current_color)
            color_button.grid(row=2, column=1, padx=10, pady=10, sticky="w")
            # 保存按钮
            def save_settings():
                try:
                    # 获取新设置
                    new_title = title_var.get().strip()
                    new_font_size = font_size_var.get()
                    new_color = color_var.get()
                    # 验证设置
                    if not new_title:
                        messagebox.showinfo("提示", "标题不能为空")
                        return
                    if new_font_size < 8 or new_font_size > 72:
                        messagebox.showinfo("提示", "字体大小应在8-72之间")
                        return
                    # 更新窗口标题
                    self.root.title(new_title)
                    # 更新配置并保存
                    global APP_CONFIG
                    APP_CONFIG["window_title"] = new_title
                    APP_CONFIG["font_size"] = new_font_size
                    APP_CONFIG["title_color"] = new_color
                    save_app_config(APP_CONFIG)
                    # 显示成功消息
                    messagebox.showinfo("成功", "设置已保存")
                    settings_window.destroy()
                except Exception as e:
                    messagebox.showerror("错误", f"保存设置失败:{e!s}")
            Button(settings_window, text="保存", command=save_settings, width=10).grid(row=3, column=1, padx=10, pady=20, sticky="e")
        except Exception as e:
            from tkinter import messagebox
            messagebox.showerror("错误", f"打开设置对话框失败:{e!s}")
    def _refresh_holding_tabs_from_news(self, run_hold_checks=False):
        """从资讯表按日期+频次刷新持仓7-14(原持仓1-持仓8):取最近8天资讯,每页为该日股票按频次排序,标签名改为MMDD。"""
        news_meta = {}
        days_data = get_news_stocks_by_date_and_frequency(ndays=8, meta=news_meta)
        if not days_data:
            reason = news_meta.get("reason")
            if reason == "db_error":
                msg = (
                    f"读取资讯表失败:{news_meta.get('error', '')}\n\n"
                    f"数据库:{DB_PATH}\n\n"
                    "若提示 database or disk is full:\n"
                    "1)清理 C: 与 D: 剩余空间;\n"
                    "2)彻底退出本程序后重新打开(启动时会把临时目录指到 D:\\StockAnalyzer\\temp,若设了 STOCK_ANALYZER_DATA_DIR 则为该目录下 temp);\n"
                    "3)仍失败时可在启动前手动设置环境变量 SQLITE_TMPDIR 到空间足够的文件夹。"
                )
            elif reason == "no_stock_dict":
                msg = "未能加载「股票代码-名称」对照表,无法从资讯正文识别六位代码。请检查网络或本地缓存后重试。"
            elif reason == "no_rows":
                msg = (
                    "资讯表(news_info)里目前没有记录。\n\n"
                    "请先使用「一键资讯」「批量爬取资讯」或各爬虫将内容保存进股票资讯表,再点「从资讯刷新」。"
                )
            elif reason == "no_valid_dates":
                msg = news_meta.get("hint") or "资讯记录无法按日期归类(created_at 异常)。"
            else:
                msg = "资讯表中暂无有效数据。请先爬取并保存资讯到股票资讯表(news_info)。"
            try:
                messagebox.showinfo("提示", msg, parent=self.root)
            except Exception:
                pass
            return
        if news_meta.get("reason") == "no_codes_in_news" or news_meta.get("total_stock_slots", -1) == 0:
            try:
                messagebox.showwarning(
                    "提示",
                    (news_meta.get("hint") or "资讯里没有解析出有效 A 股代码。")
                    + "\n\n仍会尝试按日期更新「持仓1~8」标签名,但中间股票格子可能为空。",
                    parent=self.root,
                )
            except Exception:
                pass
        for i, day_info in enumerate(days_data):
            group_index = 7 + i
            stocks = day_info.get("stocks", [])
            date_mmdd = day_info.get("date_mmdd", f"持仓{i+1}")
            holding_stocks = getattr(self, f'holding_stocks_{group_index}')
            for j in range(80):
                holding_stocks[j] = stocks[j] if j < len(stocks) else None
            notebook_index = group_index + 1
            try:
                self.position_trading_notebook.tab(notebook_index, text=date_mmdd)
            except Exception:
                pass
            for j in range(20):
                self._update_holding_label(j, check_conditions=False, group_index=group_index, fetch_daily_change=False)
        try:
            saved = self.ai_config_manager.config.get("holding_tab_names", {})
            for i, day_info in enumerate(days_data):
                saved[str(7 + i)] = day_info.get("date_mmdd", f"持仓{i+1}")
            self.ai_config_manager.config["holding_tab_names"] = saved
            self.ai_config_manager.save_config()
        except Exception:
            pass
        if run_hold_checks:
            try:
                self._run_holding_checks_for_news_tabs(include_main=True, include_date_tabs=True)
            except Exception as e:
                print(f"资讯刷新后触发持仓检测失败: {e}")
    def _refresh_main_from_news(self, silent=False, run_hold_checks=False):
        """Main 标签页:资讯表最近 5 日合并正文中的股票,按资讯内出现频次从高到低填入 holding_stocks_4。"""
        from tkinter import messagebox
        news_meta = {}
        stocks = get_news_stocks_merged_recent_days(ndays=5, meta=news_meta)
        if not stocks:
            reason = news_meta.get("reason")
            if not silent:
                if reason == "db_error":
                    msg = (
                        f"读取资讯表失败:{news_meta.get('error', '')}\n\n"
                        f"数据库:{DB_PATH}"
                    )
                elif reason == "no_stock_dict":
                    msg = "未能加载「股票代码-名称」对照表,无法从资讯正文识别六位代码。请检查网络或本地缓存后重试。"
                elif reason == "no_rows":
                    msg = (
                        "资讯表(news_info)里目前没有记录。\n\n"
                        "请先使用「一键资讯」「批量爬取资讯」或各爬虫将内容保存进股票资讯表。"
                    )
                elif reason == "no_valid_dates":
                    msg = news_meta.get("hint") or "资讯记录无法按日期归类(created_at 异常)。"
                else:
                    msg = news_meta.get("hint") or "资讯表中暂无有效 A 股代码,请先保存含六位代码的资讯。"
                try:
                    messagebox.showinfo("Main · 从资讯刷新", msg, parent=self.root)
                except Exception:
                    pass
            return
        holding_stocks, _holding_labels, _holding_kelly_results, _holding_low_diff_results = self._get_holding_group_data(4)
        for j in range(80):
            holding_stocks[j] = stocks[j] if j < len(stocks) else None
        for j in range(20):
            self._update_holding_label(j, check_conditions=False, group_index=4, fetch_daily_change=False)
        try:
            self._save_holdings_to_config(4)
        except Exception as e:
            print(f"保存 Main 持仓到配置失败: {e}")
        # 刷新持仓后检查买入信号
        try:
            self._check_buy_signal()
        except Exception as e:
            print(f"检查买入信号失败: {e}")
        if not silent:
            try:
                n = len(stocks)
                dm = news_meta.get("merged_dates_ymd") or []
                days_note = f"合并最近 {len(dm)} 个有资讯的日期" if dm else "最近5日资讯"
                messagebox.showinfo(
                    "Main · 从资讯刷新",
                    f"已按资讯频次填入 {n} 只股票({days_note},高→低)。",
                    parent=self.root,
                )
            except Exception:
                pass
        if run_hold_checks:
            try:
                self._run_holding_checks_for_news_tabs(include_main=True, include_date_tabs=True)
            except Exception as e:
                print(f"Main 资讯刷新后触发持仓检测失败: {e}")
    def _run_holding_checks_for_news_tabs(self, include_main=True, include_date_tabs=True):
        """资讯刷新后:对当期及其他日期标签页批量触发「持仓检测」按钮同源逻辑。"""
        targets = []
        if include_main:
            targets.append(4)
        if include_date_tabs:
            targets.extend(range(7, 15))
        valid_targets = []
        for g in targets:
            try:
                holding_stocks, _, _, _ = self._get_holding_group_data(g)
            except Exception:
                continue
            if any(holding_stocks):
                valid_targets.append(g)
        if not valid_targets:
            return
        names = [self._signal_tab_label_for_group(g) for g in valid_targets]
        try:
            messagebox.showinfo(
                "资讯刷新",
                "已开始批量执行持仓检测:\n" + "、".join(names),
                parent=self.root,
            )
        except Exception:
            pass
        # 逐个错峰触发,避免同一时刻并发过高
        delay_ms = 0
        for g in valid_targets:
            def _kick(group_idx=g):
                try:
                    self._check_holdings(group_index=group_idx, max_count=80)
                except Exception as _e:
                    print(f"触发持仓检测失败(group={group_idx}): {_e}")
            self.root.after(delay_ms, _kick)
            delay_ms += 1200
    def _refresh_leader_from_news(self, silent=False):
        """龙头股标签页:资讯表最近10日合并正文中的股票,按提及频次(词频)高→低填入。"""
        from tkinter import messagebox
