                # 20日数据
                pct_20d_high = alert.get('20d_high_pct', None)
                pct_20d_low = alert.get('20d_low_pct', None)
                if pct_20d_high is not None or pct_20d_low is not None:
                    nday_info = "20日:"
                    if pct_20d_high is not None:
                        sign_20h = "+" if pct_20d_high >= 0 else ""
