                    # 创建Canvas和滚动条
                    canvas = tk.Canvas(scroll_frame, bg="white")
                    scrollbar = ttk.Scrollbar(scroll_frame, orient=tk.VERTICAL, command=canvas.yview)
                    inner_frame = ttk.Frame(canvas)
