    def _show_analysis_result_dialog(self, result, stock_name, title, parent_win=None):
        """显示通用分析结果对话框(夏普比率、均值回归等)"""
        dialog = self._toplevel(parent_win or self.root)
        dialog.title(f"{stock_name} - {title}")
