        val_cb.bind("<<ComboboxSelected>>", _on_val_cb)
        for _w in val_top.winfo_children():
            _w.bind("<Button-1>", lambda e: _load_val() if e.widget != val_cb else None)
        _load_val()

        # ═══════════════════════════════════════════════════════════
